import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(depth=True);now=o.meta['proprio']['now'];P=np.array(now[22:25]);
def point(cam,u,v):
 d=o.last_depth[cam][v,u];K=np.array(o.meta['cameras'][cam]['intrinsic_cv']);E=np.array(o.meta['cameras'][cam]['extrinsic_cv']);p=np.linalg.solve(K,np.array([u*d,v*d,d]));return np.linalg.solve(E[:,:3],p-E[:,3])
def proj(cam,w):
 E=np.array(o.meta['cameras'][cam]['extrinsic_cv']);K=np.array(o.meta['cameras'][cam]['intrinsic_cv']);p=E[:,:3]@w+E[:,3];v=K@p;return v[:2]/v[2],p[2]
for uv in [(300,250),(310,250),(310,255),(300,260),(320,250)]:
 w=point('randomized_zed2_analogue_1',*uv);print('static',uv,'world',w,'wrist',proj('wrist_camera_zed_mini',w))
for uv in [(350,100),(370,110),(390,140),(350,200),(330,240)]:
 w=point('wrist_camera_zed_mini',*uv);print('wrist',uv,'world',w,'static',proj('randomized_zed2_analogue_1',w))
print('TCP',P, 'wrist',proj('wrist_camera_zed_mini',P),'static',proj('randomized_zed2_analogue_1',P))
